import{_ as s,o as e,c as a,ai as n}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"平台内核 · OpenBiz","description":"","frontmatter":{},"headers":[],"relativePath":"instances/platform.md","filePath":"instances/platform.md"}'),d={name:"instances/platform.md"};function i(r,t,o,l,p,h){return e(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="平台内核-·-openbiz" tabindex="-1">平台内核 · OpenBiz <a class="header-anchor" href="#平台内核-·-openbiz" aria-label="Permalink to “平台内核 · OpenBiz”">​</a></h1><blockquote><p>10 个垂直应用共用的底座 · 状态：✅ 多租户已验证（9 个应用接入基座）· 🔧 部分能力试水中 · 📋 多项规划 · 工程 <code>E:/8.cangku/for-job/openbiz-*</code></p></blockquote><h2 id="📌-平台简介" tabindex="-1">📌 平台简介 <a class="header-anchor" href="#📌-平台简介" aria-label="Permalink to “📌 平台简介”">​</a></h2><p>OpenBiz 不是又一个业务系统，而是「<strong>一次建深、多次复用</strong>」的企业应用底座。垂直应用只做领域模型与配置，通用能力全部下沉。</p><p>关键在于：这个底座其实有<strong>两层</strong>，很多介绍会把它们混成一句「OpenBiz 平台」。分开看才准确——</p><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>来源</th></tr></thead><tbody><tr><td><strong>L0 技术基座</strong></td><td>RuoYi 3.9.2：登录 / JWT、RBAC 权限、菜单、字典、操作日志、代码生成、Quartz 定时任务</td><td>上游开源，不重复造</td></tr><tr><td><strong>L1 应用内核</strong></td><td><code>openbiz-saas-core</code>：租户上下文、租户↔成员关系、请求级隔离注入</td><td>自研，15 个类</td></tr></tbody></table><p>垂直应用写的是第三层：<strong>领域模型 + 业务状态机 + 该领域特有的规则</strong>。</p><h2 id="🏗️-整体架构" tabindex="-1">🏗️ 整体架构 <a class="header-anchor" href="#🏗️-整体架构" aria-label="Permalink to “🏗️ 整体架构”">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌ 垂直应用层（10 个独立工程，独立端口 + 独立库）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>│  办公类（薄）   CRM · PMS · OA · BPM        各 11 个类 / 2 张表</span></span>
<span class="line"><span>│  业务类（中）   WorkOrder · ERP · HRM       7~54 个类 / 1~14 张表</span></span>
<span class="line"><span>│  工业类（厚）   MES · WMS · IIoT            43~119 个类 / 11~17 张表</span></span>
<span class="line"><span>│                                              ▲ 厚的是领域复杂度，不是基础设施</span></span>
<span class="line"><span>├ 平台内核 · OpenBiz</span></span>
<span class="line"><span>│  L1 应用内核  openbiz-saas-core〔自研 15 类〕</span></span>
<span class="line"><span>│     租户上下文 ThreadLocal · 租户↔成员 · 请求拦截注入 · 租户探针</span></span>
<span class="line"><span>│  L0 技术基座  RuoYi 3.9.2〔上游〕</span></span>
<span class="line"><span>│     登录 / JWT · RBAC · 菜单 · 字典 · 操作日志 · 代码生成 · Quartz</span></span>
<span class="line"><span>└ 数据层 · MySQL 8 · Redis · 对象存储 · 消息队列</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>两条设计主张：</p><ul><li><strong>上薄下厚</strong>：垂直应用只保留领域模型与配置，越往上越薄；通用能力全部下沉到内核。</li><li><strong>一处升级、处处受益</strong>：租户、登录、权限在内核改一次，9 个接入 L1 内核的应用同时生效。</li></ul><h2 id="🔍-mes-wms-iiot-到底用没用内核" tabindex="-1">🔍 MES / WMS / IIoT 到底用没用内核？ <a class="header-anchor" href="#🔍-mes-wms-iiot-到底用没用内核" aria-label="Permalink to “🔍 MES / WMS / IIoT 到底用没用内核？”">​</a></h2><p><strong>用到了，而且是内核最重的三个消费者。</strong> 早期版本把架构图画成只有办公类应用才接平台，那是错的。</p><h3 id="证据一-依赖声明完全一致" tabindex="-1">证据一：依赖声明完全一致 <a class="header-anchor" href="#证据一-依赖声明完全一致" aria-label="Permalink to “证据一：依赖声明完全一致”">​</a></h3><p>10 个应用的 <code>backend/pom.xml</code> 里有 9 个是同一套三件套：</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">parent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;          com.ruoyi : ruoyi : 3.9.2            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- L0 基座 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;      com.openbiz : openbiz-saas-core      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- L1 内核 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;      com.ruoyi  : ruoyi-framework         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 登录/权限外壳 --&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>统计结果：<code>openbiz-saas-core</code> 在 10 个应用里出现 <strong>9 次</strong>，唯一例外是 WorkOrder——它依赖的是 <code>openbiz-service</code> 母域模块，没有接租户内核（早期原型，见下文「诚实的边界」）。</p><h3 id="证据二-租户隔离是真的落到了-sql-里" tabindex="-1">证据二：租户隔离是真的落到了 SQL 里 <a class="header-anchor" href="#证据二-租户隔离是真的落到了-sql-里" aria-label="Permalink to “证据二：租户隔离是真的落到了 SQL 里”">​</a></h3><table tabindex="0"><thead><tr><th>应用</th><th>端口</th><th>独立库</th><th>Java 类</th><th>业务表</th><th>SQL 中 <code>tenant_id</code></th><th><code>TenantContext</code> 引用</th></tr></thead><tbody><tr><td>PMS</td><td>18083</td><td><code>openbiz_pms</code></td><td>11</td><td>2</td><td>21</td><td>2</td></tr><tr><td>CRM</td><td>18084</td><td><code>openbiz_crm</code></td><td>11</td><td>2</td><td>22</td><td>2</td></tr><tr><td>ERP</td><td>18085</td><td><code>openbiz_erp</code></td><td>39</td><td>7</td><td>68</td><td>8</td></tr><tr><td><strong>MES</strong></td><td>18082</td><td><code>openbiz_mes</code></td><td>43</td><td>13</td><td>25</td><td><strong>11</strong></td></tr><tr><td><strong>WMS</strong></td><td>18086</td><td><code>openbiz_wms</code></td><td>61</td><td>17</td><td><strong>132</strong></td><td>2</td></tr><tr><td><strong>IIoT</strong></td><td>18089</td><td><code>openbiz_iiot</code></td><td>119</td><td>11</td><td><strong>118</strong></td><td><strong>13</strong></td></tr></tbody></table><blockquote><p>口径说明：SQL 中的 <code>tenant_id</code> 统计的是<strong>全部查询与写入语句</strong>里带租户条件的次数， XML mapper 与注解式 SQL 都计入。WMS 用 MyBatis 注解（<code>@Select</code> / <code>@Insert</code> 直接写在 Mapper 接口上）， ERP / MES / IIoT 用 XML mapper——两种写法对租户隔离的要求完全一样：<strong>每一条触及业务表的语句都要带 <code>tenant_id</code></strong>， 漏一条就是跨租户数据泄漏。</p><p>「业务表」指该库中非 RuoYi 系统表（<code>sys_*</code> / <code>qrtz_*</code>）、非代码生成器表（<code>gen_*</code>）、非平台基础表（<code>openbiz_tenant</code> / <code>openbiz_member</code>）的表。ERP 的 7 张里，6 张是业务表、1 张 <code>openbiz_erp_order_seq</code> 是单号计数器。</p></blockquote><p>办公类应用（CRM / PMS / OA / BPM）各只有 <strong>11 个类、2 张表</strong>，几乎纯领域模型；工业类单应用就有 17 张表、132 处租户过滤。<strong>但它们站在同一个底座上</strong>——这正是「薄」与「厚」的正确理解：厚薄差在业务，不在基础设施。</p><h3 id="证据三-租户不是各写各的-走的同一条链路" tabindex="-1">证据三：租户不是各写各的，走的同一条链路 <a class="header-anchor" href="#证据三-租户不是各写各的-走的同一条链路" aria-label="Permalink to “证据三：租户不是各写各的，走的同一条链路”">​</a></h3><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// L1 内核：请求进入时解析，ThreadLocal 持有，请求结束必清理</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantContext.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();                                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 防 Tomcat 线程复用串租户</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Long userId </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> currentUserIdOrNull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 从 RuoYi LoginUser 取</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Long tenantId </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tenantResolver.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolveTenantId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(userId); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 查 openbiz_member</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantContext.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setTenantId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tenantId);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 垂直应用侧：直接取，不关心来源</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Long t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TenantContext.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getTenantId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();                   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// WMS StockService / IIoT IngestService / MES 均如此</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>MES 的 11 处、IIoT 的 13 处引用都套用这个模式，没有应用自己发明租户机制。</p><h3 id="内核的边界-定时任务没有「请求」" tabindex="-1">内核的边界：定时任务没有「请求」 <a class="header-anchor" href="#内核的边界-定时任务没有「请求」" aria-label="Permalink to “内核的边界：定时任务没有「请求」”">​</a></h3><p>这是接入时最早撞上的坑，也是最能说明内核边界的地方（代码注释里就写着）：</p><blockquote><p>定时任务没有请求上下文，拿不到 <code>TenantContext</code>。这里不查系统租户表，也不做半成品的跨租户遍历。</p></blockquote><p>MES 的设备轮询、IIoT 的采集任务都跑在 <code>@Scheduled</code> 里，此时 ThreadLocal 为空。当前做法是<strong>显式限定在单租户</strong>，跨租户批处理留给 P1 的「租户列表 + 上下文切换」。这类边界不写进内核，反而避免了「看起来支持多租户、实际会串数据」的假象。</p><h2 id="🧩-复用清单-谁负责什么" tabindex="-1">🧩 复用清单：谁负责什么 <a class="header-anchor" href="#🧩-复用清单-谁负责什么" aria-label="Permalink to “🧩 复用清单：谁负责什么”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>由谁提供</th><th>垂直应用要做的事</th></tr></thead><tbody><tr><td>登录 / JWT / 会话</td><td>L0 RuoYi</td><td>只配置 <code>application.yml</code>，不写认证代码</td></tr><tr><td>RBAC 角色与菜单</td><td>L0 RuoYi</td><td>写 <code>rbac_&lt;域&gt;.sql</code> 灌菜单与角色（MES / WMS 均已做）</td></tr><tr><td>字典 / 参数 / 操作日志</td><td>L0 RuoYi</td><td>直接调用，不重复实现</td></tr><tr><td>租户隔离</td><td>L1 <code>openbiz-saas-core</code></td><td>Service 里取 <code>TenantContext</code>，SQL 带 <code>tenant_id</code></td></tr><tr><td>多租户成员关系</td><td>L1 <code>openbiz-saas-core</code>（<code>openbiz_tenant</code> / <code>openbiz_member</code>）</td><td>不建同类表</td></tr><tr><td>领域状态机</td><td>各应用自建</td><td>MES / WMS / ERP 各自实现，不共享（见边界）</td></tr><tr><td>跨应用集成</td><td>各应用自建</td><td>MES → WMS/IIoT 走 HTTP 客户端 + outbox 表，<strong>不共享库</strong></td></tr><tr><td>定时任务</td><td>L0 Quartz 或 <code>@Scheduled</code></td><td>自行处理无请求上下文的租户问题</td></tr></tbody></table><p>一句话：<strong>「登录、权限、租户」一律复用；「实体、状态机、集成」一律自建。</strong></p><h2 id="🔌-接入一个新应用的标准动作" tabindex="-1">🔌 接入一个新应用的标准动作 <a class="header-anchor" href="#🔌-接入一个新应用的标准动作" aria-label="Permalink to “🔌 接入一个新应用的标准动作”">​</a></h2><p>已被 10 个应用反复验证的流程：</p><ol><li><strong>起独立工程</strong> <code>openbiz-&lt;域&gt;-app</code>：独立端口（18081–18089、18091 已用满）+ 独立库 <code>openbiz_&lt;域&gt;</code></li><li><strong>接三件套</strong>：父 POM <code>com.ruoyi:ruoyi:3.9.2</code> + <code>openbiz-saas-core</code> + <code>ruoyi-framework</code></li><li><strong>按命名约定建表</strong>：<code>openbiz_&lt;域&gt;_*</code>，业务表统一带 <code>tenant_id</code></li><li><strong>定义领域状态机</strong>：合法流转白名单 + 非法跳转拦截</li><li><strong>补 E2E 闭环</strong>，达成「可运行 → 可测试 → 有文档」</li></ol><h2 id="📦-已接入应用-10-个" tabindex="-1">📦 已接入应用（10 个） <a class="header-anchor" href="#📦-已接入应用-10-个" aria-label="Permalink to “📦 已接入应用（10 个）”">​</a></h2><table tabindex="0"><thead><tr><th>应用</th><th>端口</th><th>独立库</th><th>内核</th><th>规模</th></tr></thead><tbody><tr><td><a href="/my-vitepress-site/apps/openbiz/workorder.html">WorkOrder 服务工单</a></td><td>18081</td><td><code>openbiz_workorder</code></td><td>⚠️ 仅 L0 + <code>openbiz-service</code></td><td>7 类 / 1 表</td></tr><tr><td><a href="/my-vitepress-site/instances/industrial/mes.html">MES 生产执行</a></td><td>18082</td><td><code>openbiz_mes</code></td><td>✅ L0 + L1</td><td>41 类 / 13 表</td></tr><tr><td><a href="/my-vitepress-site/instances/business/pms.html">PMS 项目管理</a></td><td>18083</td><td><code>openbiz_pms</code></td><td>✅ L0 + L1</td><td>11 类 / 2 表</td></tr><tr><td><a href="/my-vitepress-site/instances/business/crm.html">CRM 客户关系</a></td><td>18084</td><td><code>openbiz_crm</code></td><td>✅ L0 + L1</td><td>11 类 / 2 表</td></tr><tr><td><a href="/my-vitepress-site/instances/business/erp.html">ERP 企业资源</a></td><td>18085</td><td><code>openbiz_erp</code></td><td>✅ L0 + L1</td><td>39 类 / 7 表</td></tr><tr><td><a href="/my-vitepress-site/instances/industrial/wms.html">WMS 仓储管理</a></td><td>18086</td><td><code>openbiz_wms</code></td><td>✅ L0 + L1</td><td>61 类 / 17 表</td></tr><tr><td><a href="/my-vitepress-site/instances/office/oa.html">OA 办公自动化</a></td><td>18087</td><td><code>openbiz_oa</code></td><td>✅ L0 + L1</td><td>11 类 / 2 表</td></tr><tr><td><a href="/my-vitepress-site/instances/office/bpm.html">BPM 流程管理</a></td><td>18088</td><td><code>openbiz_bpm</code></td><td>✅ L0 + L1</td><td>11 类 / 2 表</td></tr><tr><td><a href="/my-vitepress-site/instances/industrial/iiot.html">IIoT 工业物联网</a></td><td>18089</td><td><code>openbiz_iiot</code></td><td>✅ L0 + L1</td><td>119 类 / 11 表</td></tr><tr><td><a href="/my-vitepress-site/instances/office/hrm.html">HRM 人力资源</a></td><td>18091</td><td><code>openbiz_hrm</code></td><td>✅ L0 + L1</td><td>54 类 / 14 表</td></tr></tbody></table><h2 id="🚫-诚实的边界" tabindex="-1">🚫 诚实的边界 <a class="header-anchor" href="#🚫-诚实的边界" aria-label="Permalink to “🚫 诚实的边界”">​</a></h2><p>做平台最容易夸大的就是「内核覆盖了 80%」。以下是当前真实情况：</p><ul><li><strong>工作流没有下沉内核</strong>：BPM 应用自己实现流程，其他应用也各自写状态机，没有共享的流程引擎（三个工业应用均未依赖 Flowable）。</li><li><strong>只有租户内核被真正复用</strong>：基座仓库里还有 <code>openbiz-foundation</code> / <code>business</code> / <code>service</code> / <code>iot</code> / <code>shop</code> / <code>agent</code> 等母域模块，但<strong>没有一个垂直应用依赖它们</strong>（唯一例外是 WorkOrder 用了 <code>openbiz-service</code>）。它们目前是实验与归档形态，不要算进「共享内核」。</li><li><strong>WorkOrder 是唯一没接租户内核的应用</strong>：表里有 <code>tenant_id</code> 列、Mapper 也按 <code>tenantId</code> 过滤，但 Java 侧 <code>TenantContext</code> 引用为 <strong>0</strong>——租户值由兼容层从别处传入，没有走统一上下文，属于「字段有了、机制没接」的半成品；它接的是 <code>openbiz-service</code> 母域模块而非 <code>openbiz-saas-core</code>。</li><li><strong>IIoT 的权限形态与其他应用不同</strong>：对外 <code>/api/v1/**</code> 用 <code>@Anonymous</code> + <code>InternalToken</code> 自行鉴权（设备/第三方接入，不走用户登录）；管理端走通用 <code>EntityHandler</code>，因此方法级没有 <code>@PreAuthorize</code>。</li><li><strong>Form 动态表单只存在于规划</strong>：架构图里出现过 <code>Form</code>，但 10 个工程中没有对应实现。</li><li><strong>审计、消息通知、导入导出</strong>：前两项主要依赖 RuoYi 自带能力与各应用自建的 outbox，没有统一的消息中心。</li></ul><h2 id="🚀-平台演进路线" tabindex="-1">🚀 平台演进路线 <a class="header-anchor" href="#🚀-平台演进路线" aria-label="Permalink to “🚀 平台演进路线”">​</a></h2><table tabindex="0"><thead><tr><th>里程碑</th><th>内容</th><th>状态</th></tr></thead><tbody><tr><td>M1</td><td>多租户 + 独立工程骨架（当时 8 个应用接入验证，现已扩展到 9 个接 L1 内核）</td><td>✅ 完成</td></tr><tr><td>M2</td><td>租户机制补齐 WorkOrder、定时任务跨租户批处理</td><td>🔧 待做</td></tr><tr><td>M3</td><td>工作流下沉内核（当前 BPM 独占）</td><td>📋 规划</td></tr><tr><td>M4</td><td>动态表单引擎 + 统一消息中心 + 开放 API / SSO</td><td>📋 规划</td></tr></tbody></table><h2 id="🔗-相关资源" tabindex="-1">🔗 相关资源 <a class="header-anchor" href="#🔗-相关资源" aria-label="Permalink to “🔗 相关资源”">​</a></h2><ul><li>实证总览：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 实战</a></li><li>工业侧消费者：<a href="/my-vitepress-site/instances/industrial/mes.html">MES</a> · <a href="/my-vitepress-site/instances/industrial/wms.html">WMS</a> · <a href="/my-vitepress-site/instances/industrial/iiot.html">IIoT</a></li><li>办公侧消费者：<a href="/my-vitepress-site/apps/business/">功能开发 › 企业业务应用</a> · <a href="/my-vitepress-site/apps/office/">功能开发 › 办公自动化</a></li></ul><hr><p>上一级：<a href="/my-vitepress-site/instances/">项目实例总表</a> · <a href="/my-vitepress-site/instances/business/">03 企业业务应用</a></p>`,45)])])}const k=s(d,[["render",i]]);export{b as __pageData,k as default};
